export const BODY: string = "\n<p>بلک امیج ری سائزر ایک پاس میں بہت سی تصاویر کے پکسل ابعاد بدلتا ہے۔ ہر تصویر کھولنے، سائز لکھنے، اور الگ ڈاؤن لوڈ کرنے کے بجائے آپ پورا سیٹ ایک ساتھ سنبھالتے ہیں۔</p>\n<p>یہ اس لیے اہمیت رکھتا ہے کیونکہ حقیقی تصویر کام شاذ و نادر ایک تصویر ہوتا ہے۔ پروڈکٹ شوٹ چالیس تصاویر ہوتی ہے، بلاگ فولڈر بیس ہوتا ہے، اور فوٹو البم سو ہوتا ہے۔ بلک ری سائزر یہ سب ایک ساتھ سنبھالتا ہے۔</p>\n<p>اس گائیڈ میں چار سائز بدلنے کی حکمت عملی، پری سیٹ، نہ بڑھانے کی حفاظت، فارمیٹ اور کوالٹی کنٹرول، اور پورٹریٹ اور لینڈ اسکیپ ملے ہوئے بیچ کو سنبھالنا بتایا گیا ہے۔</p>\n<h2 id=\"what-is-a-bulk-image-resizer\">بلک امیج ری سائزر کیا ہے؟</h2>\n<p>بلک امیج ری سائزر ایک سائز بدلنے والا عمل پورے قطار پر لگاتا ہے۔ آپ حکمت عملی اور سائز ایک بار چنتے ہیں، اور ٹول قطار کی ہر تصویر کو اسی سے پروسیس کرتا ہے۔</p>\n<p>اہم خیال مستقل مزاجی ہے۔ پروڈکٹ کیٹلاگ پیشہ ورانہ لگتا ہے جب ہر تصویر ایک ہی چوڑائی یا ایک ہی باؤنڈنگ باکس شیئر کرے، اور بلاگ صاف لگتا ہے جب اس کی تصاویر ایک ہی سائز ہوں۔</p>\n<p>بلک سائز بدلنا ایک تصویر کو کئی بار سائز بدلنے جیسا نہیں۔ ٹول ہر فائل کو پڑھتا ہے، اسے نئے سائز پر کینوس پر کھینچتا ہے، اور تازہ فائل لکھتا ہے، بالکل واحد سائز بدلنے کی طرح۔</p>\n<p>سب کچھ آپ کے براؤزر میں مقامی طور پر چلتا ہے، آپ کے اپنے ڈیوائس پر HTML5 Canvas استعمال کرتے ہوئے۔ آپ کی تصاویر کبھی سرور پر اپ لوڈ نہیں ہوتیں، جو کلائنٹ کیٹلاگ کے لیے اہمیت رکھتا ہے۔</p>\n<h2 id=\"the-four-strategies\">چار سائز بدلنے کی حکمت عملی</h2>\n<p>بلک ری سائزر چار حکمت عملی دیتا ہے، اور درست والی چننا پورے کام کا اہم ترین فیصلہ ہے۔ ہر حکمت عملی اس بارے میں مختلف سوال کا جواب دیتی ہے کہ آخری تصویر کیسی ہونی چاہیے۔</p>\n<p>Fit Max W by H ہر تصویر کو باؤنڈنگ باکس کے اندر فٹ کرتا ہے، اپنا پہلو تناسب رکھتے ہوئے۔ Uniform Width ہر تصویر کو ایک ہی چوڑائی دیتی ہے اور اونچائی کو متناسب چلنے دیتی ہے۔</p>\n<p>حکمت عملی اس میں مختلف ہیں کہ وہ کیا ضمانت دیتی ہیں۔ Fit Max ضمانت دیتا ہے کہ کچھ کراپ یا کھینچا نہیں جائے گا۔ Uniform Width مشترکہ چوڑائی کی ضمانت دیتی ہے۔ Exact ایک جیسے ابعاد کی ضمانت دیتا ہے۔</p>\n<h2 id=\"fit-max-bounding-box\">Fit Max W by H: باؤنڈنگ باکس</h2>\n<p>Fit Max آپ کی چوڑائی اور اونچائی انٹری کو نظر نہ آنے والا ڈبہ سمجھتا ہے، ڈیفالٹ 1200 بائی 1200 پکسل۔ ہر تصویر اپنا پہلو تناسب رکھتے ہوئے اس ڈبے کے اندر فٹ ہونے کے لیے سکڑتی ہے۔</p>\n<p>1200 بائی 1200 ڈبے کے اندر 4000 بائی 2000 لینڈ اسکیپ 1200 بائی 600 بن جاتا ہے، کیونکہ چوڑائی پہلے حد کو چھوتی ہے۔ 2000 بائی 4000 پورٹریٹ 600 بائی 1200 بن جاتا ہے، کیونکہ اونچائی پہلے حد کو چھوتی ہے۔</p>\n<p>Fit Max ملے ہوئے فولڈرز کے لیے درست حکمت عملی ہے جہاں تصاویر کی سمت مختلف ہوتی ہے۔ پروڈکٹ شوٹس، بلاگ فولڈر، اور فوٹو البم سب لمبی اور چوڑی تصاویر ملاتے ہیں۔</p>\n<p>Fit Max تب استعمال کریں جب منزل زیادہ سے زیادہ سائز کے اندر مختلف ابعاد قبول کرے۔ زیادہ تر ویب سائٹس، بلاگ، اور مارکیٹ پلیس ایسا کرتے ہیں: وہ تصویر کو اس کے اپنے سائز پر دکھاتے ہیں۔</p>\n<h2 id=\"uniform-width\">Uniform Width: ہر تصویر کے لیے ایک چوڑائی</h2>\n<p>Uniform Width بیچ کی ہر تصویر کو بالکل ایک ہی چوڑائی دیتی ہے، جبکہ ہر اونچائی متناسب اسکیل ہوتی ہے۔ کچھ بھی کھینچا یا کراپ نہیں جاتا، لمبی تصاویر لمبی رہتی ہیں۔</p>\n<p>یہ عمودی لے آؤٹ کے لیے حکمت عملی ہے جہاں صف بندی اہمیت رکھتی ہے۔ نیوز لیٹر کالم، CMS مضمون کالم، یا ریسپانسیو گیلری اسٹریم سب تصاویر کو ایک ہی چوڑائی پر دکھاتے ہیں۔</p>\n<p>Uniform Width تب چنیں جب ڈسپلے چوڑائی فکسڈ ہو اور اونچائی آزاد ہو۔ بلاگ جہاں ہر مواد تصویر 1200 پکسل چوڑی ہو کلاسک صورت ہے: تصویر کی اونچائی جو بھی ہو، چوڑائی میل کھاتی ہے۔</p>\n<h2 id=\"exact-dimensions\">Exact W by H: ایک جیسے ابعاد</h2>\n<p>Exact W by H ہر تصویر کو ایک ہی چوڑائی اور اونچائی پر مجبور کرتا ہے، چاہے وہ جس شکل سے شروع ہوئی ہو۔ یہ سب سے سخت حکمت عملی ہے، اور اسے تب استعمال کریں جب منزل ایک جیسے ابعاد مانگے۔</p>\n<p>چونکہ تصاویر شاذ و نادر ایک شکل شیئر کرتی ہیں، Exact کو مماثلت سنبھالنے کے لیے فٹ برتاؤ چاہیے ہوتا ہے۔ Contain پوری تصویر کو صاف پیڈنگ حاشیوں کے ساتھ ڈبے کے اندر فٹ کرتا ہے۔</p>\n<p>Contain پروڈکٹ شاٹس کے لیے محتاط انتخاب ہے جہاں کناروں پر تفصیل ہوتی ہے۔ Cover گرڈ اور تھمب نیل کے لیے صاف انتخاب ہے جہاں بھرا ہوا فریم اہمیت رکھتا ہے۔</p>\n<h2 id=\"percentage-scaling\">فیصد: سب کچھ ایک ہی عنصر سے اسکیل کریں</h2>\n<p>Percentage موڈ ہر تصویر کی اپنی چوڑائی اور اونچائی کو آپ کے چنے ہوئے عنصر سے ضرب دیتا ہے، 10 فیصد سے 200 فیصد تک، اور 25، 50، 75، 100، اور 125 فیصد کے لیے فوری بٹن ہوتے ہیں۔</p>\n<p>50 فیصد چننے سے 4000 بائی 3000 تصویر 2000 بائی 1500 اور 1000 بائی 800 آئیکن 500 بائی 400 بن جاتا ہے، ایک ہی پاس میں۔ بڑی تصویر بڑی رہتی ہے اور چھوٹی چھوٹی رہتی ہے۔</p>\n<p>Percentage موڈ بہت بڑے فولڈر کو آدھا کرنے کا سادہ ترین طریقہ ہے۔ دیکھنے کے لیے کوئی ابعاد نہیں اور سوچنے کے لیے کوئی باؤنڈنگ باکس نہیں: 50 فیصد چنیں اور کام مکمل۔</p>\n<h2 id=\"quick-presets\">عام سائز کے لیے فوری پری سیٹ</h2>\n<p>چار فوری پری سیٹ بٹن ایک ٹیپ سے عام پکسل سائز بھرتے ہیں۔ وہ نقطہ آغاز ہیں جنہیں آپ بعد میں ایڈجسٹ کر سکتے ہیں، کیونکہ پکسل فیلڈ کوئی بھی قدر قبول کرتے ہیں۔</p>\n<p>یہ پری سیٹ سب سے عام بیچ کاموں کو پورا کرتے ہیں: فل ایچ ڈی پر ویڈیو اسٹل، 1200 پر بلاگ فولڈر، 1000 مربع پر پروڈکٹ کیٹلاگ، اور 600 پر تھمب نیل سیٹ۔</p>\n<p>منزل کے حساب سے سائز چننے پر گہری نظر کے لیے <a href=\"/ur/blog/bulk-resize-presets-social-ecommerce-print/\">Bulk Resize Presets: Social, E-commerce and Print</a> پڑھیں۔ یہ ہر پری سیٹ کو اس پلیٹفارم یا دکان سے ملاتا ہے جو اس کی توقع رکھتی ہے۔</p>\n<ul>\n<li>Full HD 1920px: 1920 بائی 1080 بھرتا ہے، معیاری وائڈ اسکرین سائز۔</li>\n<li>Blog 1200px: 1200 بائی 1200 سیٹ کرتا ہے، بلاگ مواد تصاویر کے لیے باؤنڈنگ باکس۔</li>\n<li>E-commerce 1000 by 1000: مربع پروڈکٹ سائز جو بہت سی مارکیٹ پلیس توقع رکھتی ہیں۔</li>\n<li>Thumbnail 600px: 600 بائی 600 سیٹ کرتا ہے، فہرست اور گرڈ کے لیے چھوٹا پیش نظارہ سائز۔</li>\n</ul>\n<h2 id=\"no-upscale-protection\">نہ بڑھانے کی حفاظت</h2>\n<p>Do not enlarge smaller images آپشن ملے ہوئے بیچ میں چھوٹی فائلوں کی حفاظت کرتا ہے۔ اسے چیک کرنے پر بڑی تصاویر ہدف تک سکڑتی ہیں جبکہ چھوٹی اپنے سائز پر رہتی ہیں۔</p>\n<p>یہ اس لیے اہمیت رکھتا ہے کیونکہ حقیقی فولڈر ریزولوشن ملاتے ہیں۔ 4000 پکسل DSLR شاٹس اور 400 پکسل بیج والی شوٹ بیج کو بری طرح دھندلا کر دے گی اگر انہیں بیچ ہدف تک زبردستی بڑھایا جائے۔</p>\n<h2 id=\"formats-quality-and-matte\">فارمیٹ، کوالٹی، اور میٹ پس منظر</h2>\n<p>بیچ سائز بدلنا فارمیٹ کو ایک ساتھ بدل سکتا ہے۔ Output Format کو Original سے WebP، JPG، یا PNG پر بدلنے سے ابعاد بدلتے ہیں اور فارمیٹ جدید ہو جاتا ہے۔</p>\n<p>کوالٹی سلائیڈر 10 فیصد سے 100 فیصد تک چلتا ہے اور JPG اور WebP آؤٹ پٹ پر لگتا ہے۔ 85 فیصد کے قریب ویب تصاویر کے لیے بہترین نقطہ ہے: صاف کنارے، صاف رنگ، اور مناسب فائل سائز۔</p>\n<p>JPG چننے سے Matte BG رنگ پکر ظاہر ہوتا ہے، ڈیفالٹ سفید۔ کوئی بھی شفاف پس منظر یا نرم ڈراپ شیڈو JPG میں بدلنے سے پہلے آپ کے چنے ہوئے میٹ رنگ پر رینڈر ہوتا ہے۔</p>\n<p>Original فارمیٹ رکھنے سے PNG اور WebP اپ لوڈ کے لیے شفافیت محفوظ رہتی ہے، اور PNG کے طور پر ایکسپورٹ کرنے سے ہر سائز بدلی ہوئی چیز میں الفا شفافیت برقرار رہتی ہے۔</p>\n<h2 id=\"mixed-batches\">ملے ہوئے بیچ سنبھالنا</h2>\n<p>ملے ہوئے بیچ عام صورت ہیں، استثنا نہیں۔ پروڈکٹ فولڈر لینڈ اسکیپ ہیرو شاٹس اور پورٹریٹ تفصیل شاٹس ملاتا ہے۔ بلاگ فولڈر چوڑے اسکرین شاٹس اور لمبی تصاویر ملاتا ہے۔</p>\n<p>Fit Max ملے ہوئے بیچ کے لیے بہترین ڈیفالٹ ہے، کیونکہ یہ ہر تصویر کی اپنی شکل کا احترام کرتا ہے۔ Uniform Width تب کام کرتا ہے جب ڈسپلے فکسڈ کالم ہو۔ Exact Contain کے ساتھ گرڈ کے لیے کام کرتا ہے۔</p>\n<p>ZIP ڈاؤن لوڈ کرنے سے پہلے نتائج کو کارڈ بہ کارڈ چیک کریں۔ ہر کارڈ پرانے اور نئے پکسل ابعاد دکھاتا ہے، اس لیے غلط نکلی پورٹریٹ فوراً نظر آتی ہے۔</p>\n<p>اگر بیچ کی ایک تصویر کو مختلف برتاؤ چاہیے تو اسے اس کے کارڈ پر کوڑے دان آئیکن سے ہٹائیں اور اسے الگ پروسیس کریں۔ باقی بیچ متاثر نہیں ہوتا، اور آپ کا کام جاری رہتا ہے۔</p>\n<h2 id=\"zip-workflow\">ZIP ورک فلو</h2>\n<p>درجنوں فائلیں ایک ایک کر کے ڈاؤن لوڈ کرنا سست اور غلطی کا شکار ہوتا ہے، اس لیے بلک ری سائزر بیچ کو ایک آرکائیو میں پیک کرتا ہے۔ Download All (ZIP) پر کلک کرنے سے تمام سائز بدلی ہوئی فائلیں ایک فائل میں بنتی ہیں۔</p>\n<p>ZIP آپ کے ڈیوائس پر بنتا ہے، سرور پر نہیں، اس لیے کوئی اپ لوڈ نہیں اور دور دراز کام کا انتظار نہیں۔ اندر فائل نام صاف اور پہچاننے کے قابل رہتے ہیں۔</p>\n<p>پروسیسنگ چلتے وقت ایکشن بٹن لائیو پیش رفت Resizing (X/Y) کے طور پر دکھاتا ہے، اور ابھی پروسیس ہونے والے کارڈز پر گھومتے تھمب نیل ہوتے ہیں۔ آپ ہمیشہ جانتے ہیں کہ کام کہاں ہے۔</p>\n<h2 id=\"privacy-and-local-processing\">پرائیویسی اور مقامی پروسیسنگ</h2>\n<p>ہر سائز بدلنے کا حساب، کینوس ڈرائنگ، اور ZIP بنڈل آپ کے ڈیوائس پر مقامی طور پر ہوتا ہے۔ خفیہ کلائنٹ کیٹلاگ، غیر جاری شدہ سامان، اور خاندانی البم آپ کے کمپیوٹر سے کبھی باہر نہیں جاتے۔</p>\n<p>اس مقامی پروسیسنگ کا مفید ضمنی اثر ہے: کینوس سے سائز بدلنا پکسل ڈیٹا کو دوبارہ کھینچتا ہے بغیر خام EXIF ہیڈر کاپی کیے۔ لوکیشن ٹیگ اور کیمرہ تفصیل ہٹا دی جاتی ہے۔</p>\n<h2 id=\"bulk-resize-vs-bulk-compress\">بلک سائز بدلنا بمقابلہ بلک کمپریس کرنا</h2>\n<p>بلک سائز بدلنا اور بلک کمپریشن ایک جیسے لگتے ہیں، مگر وہ مختلف چیزیں بدلتے ہیں۔ بلک ری سائزر پکسل ابعاد اور باؤنڈنگ باکس کو فعال طور پر بدلتا ہے، جبکہ بلک کمپریسر فائل سائز کو کم کرتا ہے۔</p>\n<p>ری سائزر تب استعمال کریں جب تصاویر اپنی منزل کے لیے غلط سائز کی ہوں۔ کمپریسر تب استعمال کریں جب تصاویر درست سائز کی ہوں مگر بہت بھاری ہوں۔ دونوں استعمال کریں، پہلے ری سائزر پھر کمپریسر۔</p>\n<p>دونوں خیالات کا مکمل موازنہ <a href=\"/ur/blog/resize-vs-compress-tasveer/\">Resize vs Compress: What Is the Difference?</a> میں ہے۔ کمپریسر کے لیے <a href=\"/ur/blog/bulk-tasveer-compressor-rehnumai/\">Bulk Image Compressor: Complete Guide</a> پڑھیں۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں</h2>\n<p>سب سے عام غلطی فٹ موڈ کے بارے میں سوچے بغیر ملے ہوئے بیچ کے لیے Exact ابعاد چننا ہے۔ Stretch والا Exact ہر تصویر کو بگاڑ دیتا ہے جس کی شکل ڈبے سے میل نہیں کھاتی۔</p>\n<p>دوسری غلطی ملے ہوئے فولڈر میں نہ بڑھانے کی حفاظت بند کرنا ہے۔ بیچ ہدف تک کھینچے گئے چھوٹے بیج اور آئیکن نرم ہو جاتے ہیں، اور نقصان نظر آتا ہے۔</p>\n<p>تیسری غلطی پورے بیچ کو PNG میں بدلنا ہے۔ PNG لاس لیس اور تصاویر کے لیے بھاری ہوتا ہے، اس لیے PNG میں بدلا پروڈکٹ تصاویر کا بیچ اصل سے بڑا ہو سکتا ہے۔</p>\n<h2 id=\"quick-checklist\">فوری چیک لسٹ</h2>\n<p>منزل کے لیے حکمت عملی چنیں، سائز یا پری سیٹ سیٹ کریں، نہ بڑھانے کی حفاظت آن رکھیں، فارمیٹ اور کوالٹی چنیں، پہلے چند نتائج چیک کریں، اور پھر ZIP ڈاؤن لوڈ کریں۔</p>\n<p>مرحلہ بہ مرحلہ چلانے کے لیے <a href=\"/ur/blog/ek-saath-kai-tasaveer-kaise-resize-karein/\">How to Resize Multiple Images at Once</a> پڑھیں، اور منزل کے حساب سے سائز کے لیے <a href=\"/ur/blog/bulk-resize-presets-social-ecommerce-print/\">Bulk Resize Presets: Social, E-commerce and Print</a> پڑھیں۔ <a href=\"/ur/bulk-tasveer-resize-karein/\">bulk image resizer</a> کھولیں اور شروع کریں۔</p>\n<ul>\n<li>حکمت عملی چنی گئی: ملے ہوئے فولڈرز کے لیے Fit Max، کالموں کے لیے Uniform Width، گرڈ کے لیے Exact، سادہ سکڑنے کے لیے Percentage۔</li>\n<li>سائز سیٹ: پری سیٹ، یا 1 سے 12,000 تک پکسل قدر، فی فائل 25 MB حد کے اندر۔</li>\n<li>نہ بڑھانے کی حفاظت آن، جب تک گرڈ یکساں ابعاد نہ مانگے۔</li>\n<li>فارمیٹ اور کوالٹی سیٹ: تصاویر کے لیے 85 فیصد کے قریب WebP یا JPG، شفافیت کے لیے PNG۔</li>\n<li>پہلے نتائج Compare منظر میں چیک کیے گئے، پھر ZIP ڈاؤن لوڈ کیا گیا۔</li>\n</ul>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ایک بیچ میں ایک ساتھ کتنی تصاویر کا سائز بدل سکتا ہوں؟","answer":"ٹول میں کوئی فکسڈ تعداد حد نہیں ہے: آپ ایک بیچ میں درجنوں تصاویر قطار میں لگا سکتے ہیں، ہر ایک 25 MB تک۔ عملی حد آپ کے ڈیوائس کی میموری ہے، کیونکہ ہر تصویر آپ کے براؤزر میں کینوس پر کھینچی جاتی ہے۔"},{"question":"کیا بلک سائز بدلنے کے لیے اکاؤنٹ یا سائن اپ چاہیے؟","answer":"نہیں۔ بلک امیج ری سائزر مکمل طور پر آپ کے براؤزر میں چلتا ہے بغیر اکاؤنٹ، بغیر سائن اپ، اور بغیر اپ لوڈ کے۔ صفحہ کھولیں، اپنی تصاویر ڈالیں، حکمت عملی چنیں، اور ZIP ڈاؤن لوڈ کریں۔ آپ کے بیچ کے بارے میں کچھ بھی کہیں نہیں جاتا۔"},{"question":"کیا میں اپنے فون پر بلک سائز بدل سکتا ہوں؟","answer":"ہاں۔ بلک ری سائزر ٹچ دوست کنٹرول والے موبائل براؤزرز میں کام کرتا ہے، اور آپ اپنی فوٹو لائبریری سے اپ لوڈ کر سکتے ہیں۔ فون پر بیچ معمولی رکھیں، کیونکہ بڑے کینوس زیادہ میموری استعمال کرتے ہیں، اور تازہ ترین براؤزر استعمال کریں۔"},{"question":"کیا میری اصل فائلیں بلک سائز بدلنے سے بدل جائیں گی؟","answer":"نہیں۔ ٹول آپ کے اصل پڑھتا ہے اور تازہ سائز بدلی ہوئی فائلیں لکھتا ہے، اور اصل آپ کے ڈیوائس پر بغیر چھوئے رہتے ہیں۔ آپ دوبارہ اپ لوڈ کیے بغیر ایک ہی بیچ کو مختلف سیٹنگ سے دوبارہ چلا سکتے ہیں۔"},{"question":"کیا میں ایک بیچ میں مختلف تصاویر کے لیے مختلف سیٹنگ استعمال کر سکتا ہوں؟","answer":"نہیں، ایک بیچ قطار کی ہر تصویر کے لیے ایک حکمت عملی اور ایک سیٹنگ سیٹ استعمال کرتا ہے۔ اگر کچھ تصاویر کو مختلف برتاؤ چاہیے تو انہیں الگ بیچ کے طور پر چلائیں، یا عجیب والیوں کو کوڑے دان آئیکن سے ہٹائیں۔"},{"question":"بیچ سائز بدلنے کے بعد تصویر دھندلی لگے تو کیا کروں؟","answer":"پہلے چیک کریں کہ کیا چھوٹی تصویر بڑھائی گئی تھی: یقینی بنائیں کہ Do not enlarge smaller images چیک ہے اور بیچ دوبارہ چلائیں۔ پھر کوالٹی سیٹنگ چیک کریں، کیونکہ بہت کم کوالٹی تفصیل نرم کر دیتی ہے۔ اگر مسئلہ جاری رہے تو اصل سے دوبارہ چلائیں۔"}];
